// ═══════════════════════════════════════════════════════════════
// ADD YOUR GOOGLE DRIVE FOLDER IDs HERE
// Get a folder ID from its URL:
//   https://drive.google.com/drive/folders/THIS_PART_IS_THE_ID
// ═══════════════════════════════════════════════════════════════
const FOLDERS = [
  { id: 'REPLACE_WITH_FOLDER_ID_1', label: '2025 Knowledge Folder' },
  { id: 'REPLACE_WITH_FOLDER_ID_2', label: 'Books' },
  // { id: 'REPLACE_WITH_FOLDER_ID_3', label: 'Meeting Notes' },
];
// ═══════════════════════════════════════════════════════════════

// Read last-run timestamp from workflow static data
const staticData = $getWorkflowStaticData('global');
const lastRun = staticData.lastRun
  || new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString(); // default: 24h ago on first run

// Save new timestamp now so we don't miss files if the run fails partway
const newRun = new Date().toISOString();
staticData.lastRun = newRun;

console.log(`Checking for files modified after: ${lastRun}`);

// Return one item per folder — n8n will run the next node once per item
return FOLDERS.map(folder => ({
  json: {
    folderId:    folder.id,
    folderLabel: folder.label,
    lastRunISO:  lastRun,
    newRunISO:   newRun,
  }
}));

// Filter to supported file types only and tag each file with its folder label
const SUPPORTED_MIME = [
  'text/plain',
  'text/markdown',
  'application/pdf',
  'application/vnd.google-apps.document', // Google Docs (exported as plain text)
];
const SUPPORTED_EXT = ['.md', '.txt', '.rst', '.pdf'];

const results = [];
for (const item of $input.all()) {
  const mime = item.json.mimeType || '';
  const name = item.json.name || '';
  const ext  = name.includes('.') ? '.' + name.split('.').pop().toLowerCase() : '';

  const supported = SUPPORTED_MIME.includes(mime) || SUPPORTED_EXT.includes(ext);
  if (!supported) continue;

  results.push({
    json: {
      ...item.json,
      folderLabel: item.json.folderLabel || 'unknown',
    }
  });
}

console.log(`Found ${results.length} supported files to process`);
return results;

// ── Config ───────────────────────────────────────────────────────────────────
const CHUNK_WORDS   = 600;
const OVERLAP_WORDS = 80;
const MIN_WORDS     = 30;

// ── Helpers ──────────────────────────────────────────────────────────────────
function wordChunks(words) {
  const chunks = [];
  let i = 0;
  while (i < words.length) {
    const chunk = words.slice(i, i + CHUNK_WORDS);
    if (chunk.length >= MIN_WORDS) chunks.push(chunk.join(' '));
    i += CHUNK_WORDS - OVERLAP_WORDS;
  }
  return chunks;
}

function parseFrontmatter(text) {
  const match = text.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n/);
  if (!match) return { meta: {}, body: text };
  const meta = {};
  let currentKey = null;
  for (const line of match[1].split('\n')) {
    const listItem = line.match(/^\s+-\s+"?([^"]+)"?\s*$/);
    const kv       = line.match(/^([\w][\w\s]*?):\s*(.*)/);
    if (listItem && currentKey) {
      if (!Array.isArray(meta[currentKey])) meta[currentKey] = [];
      meta[currentKey].push(listItem[1].trim());
    } else if (kv) {
      currentKey = kv[1].trim();
      meta[currentKey] = kv[2].trim().replace(/^"|"$/g, '');
    }
  }
  // Normalise tags to array
  const raw = meta.tags || [];
  meta.tags = Array.isArray(raw)
    ? raw.map(t => String(t).trim())
    : String(raw).split(',').map(t => t.trim()).filter(Boolean);
  return { meta, body: text.slice(match[0].length) };
}

function chunkMarkdown(text) {
  const sections = text.split(/\n(?=#{1,3} )/);
  const result = [];
  for (const section of sections) {
    const lines   = section.trim().split('\n');
    const heading = lines[0].startsWith('#') ? lines[0].replace(/^#+\s*/, '') : '';
    const body    = lines.slice(1).join(' ').trim();
    if (!body) continue;
    const words  = body.split(/\s+/);
    const prefix = heading ? `${heading}: ` : '';
    if (words.length <= CHUNK_WORDS) {
      result.push({ section: heading, text: prefix + body });
    } else {
      for (const chunk of wordChunks(words)) {
        result.push({ section: heading, text: prefix + chunk });
      }
    }
  }
  return result;
}

function chunkPlain(text) {
  const paras  = text.split(/\n{2,}/).map(p => p.trim()).filter(Boolean);
  let buffer   = [];
  const result = [];
  for (const para of paras) {
    buffer.push(...para.split(/\s+/));
    while (buffer.length >= CHUNK_WORDS) {
      result.push({ section: '', text: buffer.slice(0, CHUNK_WORDS).join(' ') });
      buffer = buffer.slice(CHUNK_WORDS - OVERLAP_WORDS);
    }
  }
  if (buffer.length >= MIN_WORDS) result.push({ section: '', text: buffer.join(' ') });
  return result;
}

function stableHash(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    hash = ((hash << 5) - hash) + str.charCodeAt(i);
    hash |= 0;
  }
  return Math.abs(hash).toString(16).padStart(8, '0');
}

// ── Main (runs once per file) ─────────────────────────────────────────────────
const results = [];

for (const item of $input.all()) {
  const file     = item.json;
  const fileName = file.name || 'unknown';
  const ext      = fileName.includes('.') ? fileName.split('.').pop().toLowerCase() : '';
  const isMarkdown = ext === 'md' || (file.mimeType || '').includes('markdown');

  // Get raw text from binary
  let rawText = '';
  if (item.binary && item.binary.data) {
    rawText = Buffer.from(item.binary.data.data, 'base64').toString('utf-8');
  } else {
    console.log(`Skipping ${fileName} — no binary content`);
    continue;
  }

  // Parse frontmatter for markdown
  const { meta, body } = isMarkdown ? parseFrontmatter(rawText) : { meta: {}, body: rawText };

  // Chunk
  const chunks = isMarkdown ? chunkMarkdown(body) : chunkPlain(body);
  if (!chunks.length) continue;

  const source   = file.webViewLink || file.id || fileName;
  const title    = String(meta.title || '').trim() || fileName.replace(/\.\w+$/, '').replace(/[-_]/g, ' ');
  const docType  = isMarkdown ? 'markdown' : (ext === 'pdf' ? 'book' : 'notes');
  const tags     = (meta.tags || []).join(',');
  const now      = Math.floor(Date.now() / 1000);
  const total    = chunks.length;
  const stem     = fileName.slice(0, 20).replace(/\W/g, '_');

  for (let i = 0; i < chunks.length; i++) {
    const c = chunks[i];
    if (c.text.split(/\s+/).length < MIN_WORDS) continue;
    results.push({
      json: {
        _id:         `${stem}_${stableHash(source + i)}`,
        text:        c.text,
        source,
        title,
        doc_type:    docType,
        section:     c.section,
        chunk_index: i,
        chunk_count: total,
        timestamp:   now,
        tags,
        folder:      file.folderLabel || '',
      }
    });
  }
}

console.log(`Generated ${results.length} chunks from ${$input.all().length} files`);
return results;
